#pragma unroll
    for (int nt = 0; nt < 2; ++nt)
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int raw = __ldg(myidx + t * kKeyTile + gid * kKeysPerQk + nt * 8 +
                              cq * 2 + j);
        valid[nt][j] = (raw >= 0 && raw < ntokens) ? 1.f : 0.f;
      }

#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int nt = 0; nt < 2; ++nt)
#pragma unroll
        for (int j = 0; j < 2; ++j) {
          const float mask0 = valid[nt][0] ? 1.f : 0.f;
          const float mask1 = valid[nt][1] ? 1.f : 0.f;
