460	void check_input(const torch::Tensor& t, at::ScalarType dtype, int dim,
461	                 const char* name) {
462	  TORCH_CHECK_VALUE(t.is_cuda(), name, " must be CUDA");
463	  TORCH_CHECK_TYPE(t.scalar_type() == dtype, name, " dtype mismatch");
464	  TORCH_CHECK_VALUE(t.dim() == dim, name, " rank mismatch");
465	  TORCH_CHECK_VALUE(t.is_contiguous(), name, " must be contiguous");
466	}
467	
468	void kernel(const torch::Tensor& q, const torch::Tensor& kv,
469	            const torch::Tensor& indices, const torch::Tensor& output,
470	            const torch::Tensor& max_logits, const torch::Tensor& lse) {
471	  check_input(q, torch::kBFloat16, 3, "q");
472	  check_input(kv, torch::kBFloat16, 3, "kv");
473	  check_input(indices, torch::kInt32, 3, "indices");
474	  check_input(output, torch::kBFloat16, 3, "output");
475	  check_input(max_logits, torch::kFloat32, 2, "max_logits");
476	  check_input(lse, torch::kFloat32, 2, "lse");
477	
478	  const int64_t ntokens = q.size(0);
479	  TORCH_CHECK_VALUE(q.size(1) == kHeads && kv.size(0) == ntokens &&
480	                        indices.size(0) == ntokens,
481	                    "unexpected problem shape");
482	  TORCH_CHECK_VALUE(q.size(2) == kQkDim && kv.size(2) == kQkDim &&
483	                        indices.size(2) == kTopK && indices.size(1) == 1,
484	                    "unexpected problem shape");
485	  TORCH_CHECK_VALUE(output.size(2) == kValueDim && output.size(1) == kHeads,
486	                    "unexpected output shape");
487	  TORCH_CHECK_VALUE(q.device() == kv.device() && q.device() == indices.device() &&
488	                        q.device() == output.device() &&
489	                        q.device() == max_logits.device(),
490	                    "device mismatch");
491	
492	  c10::cuda::CUDAGuard guard(q.device());
493	  const cudaStream_t stream =
494	      c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
495	
496	  static bool configured = false;
497	  if (!configured) {
498	    const cudaError_t attr = cudaFuncSetAttribute(
499	        sparse_mla_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
500	        kSmemBytes);
501	    TORCH_CHECK(attr == cudaSuccess, cudaGetErrorString(attr));
502	    configured = true;
503	  }
504	
505	  const dim3 grid((unsigned)ntokens, kHeads / kHeadBlock);
506	  sparse_mla_kernel<<<grid, kThreads, kSmemBytes, stream>>>(
507	      reinterpret_cast<const bf16*>(q.data_ptr<at::BFloat16>()),
508	      reinterpret_cast<const bf16*>(kv.data_ptr<at::BFloat16>()),
509	      indices.data_ptr<int>(), (int)ntokens,
510	      reinterpret_cast<bf16*>(output.data_ptr<at::BFloat16>()),
511	      max_logits.data_ptr<float>(), lse.data_ptr<float>());
512	  const cudaError_t err = cudaGetLastError();
513	  TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
514	}
