 34	// Stage 64 rows of a [rows][576] bf16 source straight into a swizzled tile.
 35	// A warp owns 8 rows; 72 chunks per row are covered by 3 passes over 32 lanes.
 36	__device__ __forceinline__ void stage_dense(bf16* dst, const bf16* src,
 37	                                            int tid) {
 38	  const int lane = tid & 31;
 39	  const int wid = tid >> 5;
 40	  constexpr int kRowsPerWarp = kKeyTile / kWarps;
 41	#pragma unroll
 42	  for (int r = 0; r < kRowsPerWarp; ++r) {
 43	    const int row = wid * kRowsPerWarp + r;
 44	    const bf16* srow = src + (size_t)row * kQkDim;
 45	    bf16* drow = dst + row * kQkDim;
 46	#pragma unroll
 47	    for (int j = 0; j < 3; ++j) {
 48	      const int c = j * 32 + lane;
 49	      if (c < kChunksPerRow)
 50	        cp_async16(sm_addr(drow + swz_chunk(row, c) * 8), srow + c * 8, 16);
 51	    }
 52	  }
 53	}
