 55	// Same, but rows come from the sparse index list; an invalid index is staged as
 56	// zero (cp.async src_bytes = 0 zero-fills) and later masked to -inf.
 57	__device__ __forceinline__ void stage_gather(bf16* dst, const bf16* kv,
 58	                                             const int* idx, int ntokens,
 59	                                             int tid) {
 60	  const int lane = tid & 31;
 61	  const int wid = tid >> 5;
 62	  constexpr int kRowsPerWarp = kKeyTile / kWarps;
 63	#pragma unroll
 64	  for (int r = 0; r < kRowsPerWarp; ++r) {
 65	    const int row = wid * kRowsPerWarp + r;
 66	    const int raw = __ldg(idx + row);
 67	    const bool ok = (raw >= 0) && (raw < ntokens);
 68	    const bf16* srow = kv + (size_t)(ok ? raw : 0) * kQkDim;
 69	    bf16* drow = dst + row * kQkDim;
 70	#pragma unroll
 71	    for (int j = 0; j < 3; ++j) {
 72	      const int c = j * 32 + lane;
 73	      if (c < kChunksPerRow)
 74	        cp_async16(sm_addr(drow + swz_chunk(row, c) * 8), srow + c * 8,
 75	                   ok ? 16 : 0);
 76	    }
 77	  }
 78	}
