 80	__global__ void __launch_bounds__(kThreads, 1)
 81	sparse_mla_kernel(const bf16* __restrict__ q, const bf16* __restrict__ kv,
 82	                  const int* __restrict__ ind, int ntokens,
 83	                  bf16* __restrict__ out, float* __restrict__ maxlog,
 84	                  float* __restrict__ lse) {
 85	#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 800
 86	  extern __shared__ char smem[];
 87	  bf16* Qs = reinterpret_cast<bf16*>(smem);
 88	  bf16* KVs = Qs + kQElems;
 89	  bf16* Ps = KVs + 2 * kKvElems;
 90	  float* pMax = reinterpret_cast<float*>(Ps + kPElems);
 91	  float* pSum = pMax + kStatElems;
 92	
 93	  const int tok = blockIdx.x;
 94	  const int h0 = blockIdx.y * kHeadBlock;
 95	  const int tid = threadIdx.x;
 96	  const int lane = tid & 31;
 97	  const int wid = tid >> 5;
 98	  const int mg = wid >> 2;   // head half of this warp
 99	  const int gid = wid & 3;   // key slice (QK) and value slice (PV)
100	  const int lr = lane & 7;   // row inside an ldmatrix tile
101	  const int lg = lane >> 3;  // ldmatrix tile selector
102	  const int hq = lane >> 2;  // row pair inside a 16x8 fragment
103	  const int cq = lane & 3;   // column pair inside a 16x8 fragment
104	  const int barid = 1 + mg;
105	
106	  // A fragment rows: head rows of this warp's 32-head half.
107	  const int qrow0 = mg * kHeadsPerHalf + ((lg & 1) << 3) + lr;
108	  const int qrow1 = qrow0 + 16;
109	  const int qbase0 = qrow0 * kChunksPerRow;
110	  const int qbase1 = qrow1 * kChunksPerRow;
111	  const int qlow0 = qrow0 & kSwzMask;
112	  const int qlow1 = qrow1 & kSwzMask;
113	  // B fragment rows: key rows of this warp's 16-key slice.
114	  const int krow = gid * kKeysPerQk + ((lg & 1) << 3) + lr;
115	  const int kbase = krow * kChunksPerRow;
116	  const int klow = krow & kSwzMask;
117	  const int cadd = lg >> 1;  // second chunk of a 16 element k-step
118	  // V fragment rows: keys of the current 16-key k-step.
119	  const int vrow = ((lg & 1) << 3) + lr;
120	  const int vlow = vrow & kSwzMask;
121	
122	  const int* myidx = ind + (size_t)tok * kTopK;
123	  const bf16* qsrc = q + (size_t)tok * kHeads * kQkDim + (size_t)h0 * kQkDim;
124	
125	  // ---- prologue: query tile + first key tile -----------------------------
126	  stage_dense(Qs, qsrc, tid);
127	  stage_gather(KVs, kv, myidx, ntokens, tid);
128	  cp_commit();
129	
130	  float acc[2][16][4];
131	#pragma unroll
132	  for (int mt = 0; mt < 2; ++mt)
133	#pragma unroll
134	    for (int nt = 0; nt < 16; ++nt)
135	#pragma unroll
136	      for (int i = 0; i < 4; ++i) acc[mt][nt][i] = 0.f;
137	
138	  float mrun[4];
139	  float msh[4];
140	  float lrun[4];
141	#pragma unroll
142	  for (int i = 0; i < 4; ++i) {
143	    mrun[i] = -INFINITY;
144	    msh[i] = 0.f;
145	    lrun[i] = 0.f;
146	  }
147	
148	  for (int t = 0; t < kNumTiles; ++t) {
149	    cp_wait_all();
150	    __syncthreads();
151	    if (t + 1 < kNumTiles)
152	      stage_gather(KVs + ((t + 1) & 1) * kKvElems, kv, myidx + (t + 1) * kKeyTile,
153	                   ntokens, tid);
154	    cp_commit();
155	
156	    const bf16* kvbuf = KVs + (t & 1) * kKvElems;
157	
158	    // ---- QK^T over this warp's 16-key slice ------------------------------
159	    float s[2][2][4];
160	#pragma unroll
161	    for (int mt = 0; mt < 2; ++mt)
162	#pragma unroll
163	      for (int nt = 0; nt < 2; ++nt)
164	#pragma unroll
165	        for (int i = 0; i < 4; ++i) s[mt][nt][i] = 0.f;
166	
167	#pragma unroll
168	    for (int ks = 0; ks < kStepQk; ++ks) {
169	      const int c = ks * 2 + cadd;
170	      uint32_t a0[4], a1[4], b[4];
171	      ldsm_x4(tile_addr(Qs, qbase0, qlow0, c), a0);
172	      ldsm_x4(tile_addr(Qs, qbase1, qlow1, c), a1);
173	      ldsm_x4(tile_addr(kvbuf, kbase, klow, c), b);
174	      mma_bf16(s[0][0], a0, b[0], b[2]);
175	      mma_bf16(s[0][1], a0, b[1], b[3]);
176	      mma_bf16(s[1][0], a1, b[0], b[2]);
177	      mma_bf16(s[1][1], a1, b[1], b[3]);
178	    }
179	
180	    // ---- mask, scale, per-row max ---------------------------------------
181	    float valid[2][2];
182	#pragma unroll
183	    for (int nt = 0; nt < 2; ++nt)
184	#pragma unroll
185	      for (int j = 0; j < 2; ++j) {
186	        const int raw = __ldg(myidx + t * kKeyTile + gid * kKeysPerQk + nt * 8 +
187	                              cq * 2 + j);
188	        valid[nt][j] = (raw >= 0 && raw < ntokens) ? 1.f : 0.f;
189	      }
190	
191	#pragma unroll
192	    for (int mt = 0; mt < 2; ++mt)
193	#pragma unroll
194	      for (int nt = 0; nt < 2; ++nt)
195	#pragma unroll
196	        for (int j = 0; j < 2; ++j) {
197	          const float mask0 = valid[nt][0] ? 1.f : 0.f;
198	          const float mask1 = valid[nt][1] ? 1.f : 0.f;
199	          float v0 = s[mt][nt][j * 2 + 0] * kScale;
200	          float v1 = s[mt][nt][j * 2 + 1] * kScale;
201	          s[mt][nt][j * 2 + 0] = mask0 ? v0 : -INFINITY;

          s[mt][nt][j * 2 + 0] = mask0 ? v0 : -INFINITY;
          s[mt][nt][j * 2 + 1] = mask1 ? v1 : -INFINITY;
        }

    float tmax[4];
#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        float m = fmaxf(fmaxf(s[mt][0][j * 2], s[mt][0][j * 2 + 1]),
                        fmaxf(s[mt][1][j * 2], s[mt][1][j * 2 + 1]));
        m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, 1));
        m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, 2));
        tmax[mt * 2 + j] = m;
      }
    if (cq == 0) {
#pragma unroll
      for (int mt = 0; mt < 2; ++mt)
#pragma unroll
        for (int j = 0; j < 2; ++j)
          pMax[mg * (32 * 4) + (mt * 16 + hq + j * 8) * 4 + gid] = tmax[mt * 2 + j];
    }
    bar_sync(barid, 128);

    // ---- rescale the accumulator, then emit probabilities ----------------
    float alpha[4];
#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int i = mt * 2 + j;
        const float4 pm =
            *reinterpret_cast<const float4*>(pMax + mg * (32 * 4) +
                                             (mt * 16 + hq + j * 8) * 4);
        const float tile = fmaxf(fmaxf(pm.x, pm.y), fmaxf(pm.z, pm.w));
        const float mnew = fmaxf(mrun[i], tile);
        msh[i] = (mnew == -INFINITY) ? 0.f : mnew;
        alpha[i] = __expf(mrun[i] - msh[i]);
        mrun[i] = mnew;
      }
#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int nt = 0; nt < 16; ++nt) {
        const float a0 = alpha[mt * 2 + 0];
        const float a1 = alpha[mt * 2 + 1];
        acc[mt][nt][0] *= a0;
        acc[mt][nt][1] *= a0;
        acc[mt][nt][2] *= a1;
        acc[mt][nt][3] *= a1;
      }

    float lsum[4];
#pragma unroll
    for (int i = 0; i < 4; ++i) lsum[i] = 0.f;
#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int nt = 0; nt < 2; ++nt)
#pragma unroll
        for (int j = 0; j < 2; ++j) {
          const int i = mt * 2 + j;
          const int row = (mt * 16 + hq + j * 8);
          const float a0 = s[mt][nt][j * 2 + 0] - msh[i];
          const float a1 = s[mt][nt][j * 2 + 1] - msh[i];
          const uint16_t h0 = to_bf16(__expf(a0));
          const uint16_t h1 = to_bf16(__expf(a1));
          *reinterpret_cast<uint32_t*>(
              Ps + mg * (32 * kKeyTile) +
              (row * 8 + swz_chunk(row, gid * 2 + nt)) * 8 + cq * 2) =
              (uint32_t)h0 | ((uint32_t)h1 << 16);
          lsum[i] += from_bf16(h0) + from_bf16(h1);
        }
#pragma unroll
    for (int i = 0; i < 4; ++i) {
      float v = lsum[i];
      v += __shfl_xor_sync(0xffffffffu, v, 1);
      v += __shfl_xor_sync(0xffffffffu, v, 2);
      lsum[i] = v;
    }
    if (cq == 0) {
#pragma unroll
      for (int mt = 0; mt < 2; ++mt)
#pragma unroll
        for (int j = 0; j < 2; ++j)
          pSum[mg * (32 * 4) + (mt * 16 + hq + j * 8) * 4 + gid] = lsum[mt * 2 + j];
    }
    bar_sync(barid, 128);

#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int i = mt * 2 + j;
        const float4 ps =
            *reinterpret_cast<const float4*>(pSum + mg * (32 * 4) +
                                             (mt * 16 + hq + j * 8) * 4);
        lrun[i] = lrun[i] * alpha[i] + ((ps.x + ps.y) + (ps.z + ps.w));
      }

    // ---- P @ V -----------------------------------------------------------
    const int vchunk0 = gid * 16;
#pragma unroll
    for (int kk = 0; kk < kStepPv; ++kk) {
      const bf16* pgrp = Ps + mg * (32 * kKeyTile);
      uint32_t a[2][4];
      ldsm_x4(p_addr(pgrp, ((lg & 1) << 3) + lr, kk * 2 + cadd), a[0]);
      ldsm_x4(p_addr(pgrp, ((lg & 1) << 3) + lr + 16, kk * 2 + cadd), a[1]);
      const bf16* vbase = kvbuf + (16 * kk) * kQkDim;
#pragma unroll
      for (int jj = 0; jj < 8; ++jj) {
        uint32_t b[4];
        ldsm_x4_t(tile_addr(vbase, vrow * kChunksPerRow, vlow,
                            vchunk0 + jj * 2 + cadd),
                  b);
        mma_bf16(acc[0][jj * 2 + 0], a[0], b[0], b[1]);
        mma_bf16(acc[0][jj * 2 + 1], a[0], b[2], b[3]);
        mma_bf16(acc[1][jj * 2 + 0], a[1], b[0], b[1]);
        mma_bf16(acc[1][jj * 2 + 1], a[1], b[2], b[3]);
      }
    }
  }

  // ---- epilogue ----------------------------------------------------------
  float rcp[4];
#pragma unroll
  for (int i = 0; i < 4; ++i) rcp[i] = (lrun[i] > 0.f) ? 1.f / lrun[i] : 0.f;
#pragma unroll
  for (int mt = 0; mt < 2; ++mt)
#pragma unroll
    for (int nt = 0; nt < 16; ++nt) {
      const int head = h0 + mg * kHeadsPerHalf + mt * 16 + hq;
      const int vcol = gid * kValPerWarp + nt * 8 + cq * 2;
      bf16* dst = out + (size_t)tok * kHeads * kValueDim +
                  (size_t)head * kValueDim + vcol;
      const float r0 = rcp[mt * 2 + 0];
      const float r1 = rcp[mt * 2 + 1];
      const uint16_t lo0 = to_bf16(acc[mt][nt][0] * r0);
      const uint16_t hi0 = to_bf16(acc[mt][nt][1] * r0);
      const uint16_t lo1 = to_bf16(acc[mt][nt][2] * r1);
      const uint16_t hi1 = to_bf16(acc[mt][nt][3] * r1);
      *reinterpret_cast<uint32_t*>(dst) =
          (uint32_t)lo0 | ((uint32_t)hi0 << 16);
      *reinterpret_cast<uint32_t*>(dst + 8 * kValueDim) =
          (uint32_t)lo1 | ((uint32_t)hi1 << 16);
    }
  if (cq == 0) {
#pragma unroll
    for (int mt = 0; mt < 2; ++mt)
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int i = mt * 2 + j;
        const int head = h0 + mg * kHeadsPerHalf + mt * 16 + hq + j * 8;
        maxlog[(size_t)tok * kHeads + head] = mrun[i];
        lse[(size_t)tok * kHeads + head] = mrun[i] + logf(lrun[i]);
      }
  }
#endif
