// Test 1: S = A @ Bstored^T ; A [16][16] row-major pitch PA ; Bstored [16][16] row-major pitch PB
// warp computes S[16][16] using 2 n-tiles.
__global__ void t1(const __nv_bfloat16* A, const __nv_bfloat16* Bs, int PA, int PB, float* S) {
  __shared__ __nv_bfloat16 sa[16][16];
  __shared__ __nv_bfloat16 sb[16][16];
  int tid = threadIdx.x;
  for (int i = tid; i < 256; i += 32) { ((__nv_bfloat16*)sa)[i] = A[(i/16)*PA + (i%16)]; }
  for (int i = tid; i < 256; i += 32) { ((__nv_bfloat16*)sb)[i] = Bs[(i/16)*PB + (i%16)]; }
  __syncwarp();
  int lane = tid & 31;
  int g = lane >> 3;      // 0..3
  int r = lane & 7;       // 0..7
  // A: m16k16, tiles (0..7,0..7),(8..15,0..7),(0..7,8..15),(8..15,8..15)
  int arow = ((g & 1) << 3) + r;
  int acol = (g >> 1) << 3;
  uint32_t a0,a1,a2,a3;
  ldsm_x4(smem_u32(&sa[arow][acol]), a0,a1,a2,a3);
  // B: rows = n (keys), cols = k(dims). tiles (0..7,0..7),(8..15,0..7),(0..7,8..15),(8..15,8..15)
  int brow = ((g & 1) << 3) + r;
  int bcol = (g >> 1) << 3;
  uint32_t b0,b1,b2,b3;
  ldsm_x4(smem_u32(&sb[brow][bcol]), b0,b1,b2,b3);
  float d0[4] = {0,0,0,0}, d1[4] = {0,0,0,0};
  mma_bf16(d0, a0,a1,a2,a3, b0, b2);
  mma_bf16(d1, a0,a1,a2,a3, b1, b3);
  // write out: d0 -> columns 0..7 (n tile 0), d1 -> columns 8..15
  int cr = lane >> 2, cc = (lane & 3) * 2;
  for (int j = 0; j < 2; j++) {
    S[(cr)*16 + cc + j]        = d0[j];
    S[(cr+8)*16 + cc + j]      = d0[2+j];
    S[(cr)*16 + 8 + cc + j]    = d1[j];
    S[(cr+8)*16 + 8 + cc + j]  = d1[2+j];
  }
}

